import{_ as e,o as l,c as t,a2 as r}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"篇915｜万族共和文明宪章·第十四条——跨位面操作报备制","description":"","frontmatter":{"title":"篇915｜万族共和文明宪章·第十四条——跨位面操作报备制","no":915,"module":5,"tags":["宪章","第十四条","跨位面","报备制","操作规范"],"related":["81-位面穿梭规则","88-跨位面伦理准则","28-跨位面锚点连接"]},"headers":[],"relativePath":"zh/915_模块5-第十四条-跨位面操作报备制.md","filePath":"zh/915_模块5-第十四条-跨位面操作报备制.md"}'),i={name:"zh/915_模块5-第十四条-跨位面操作报备制.md"};function o(h,a,n,p,d,s){return l(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="篇915-万族共和文明宪章·第十四条——跨位面操作报备制" tabindex="-1">篇915｜万族共和文明宪章·第十四条——跨位面操作报备制 <a class="header-anchor" href="#篇915-万族共和文明宪章·第十四条——跨位面操作报备制" aria-label="Permalink to &quot;篇915｜万族共和文明宪章·第十四条——跨位面操作报备制&quot;">​</a></h1><blockquote><p>所属模块：模块五·文明终极定型典藏篇｜对标地基：文档81、88、28</p></blockquote><h2 id="引言-每次跨位面-都要留下名字" tabindex="-1">引言：每次跨位面，都要留下名字 <a class="header-anchor" href="#引言-每次跨位面-都要留下名字" aria-label="Permalink to &quot;引言：每次跨位面，都要留下名字&quot;">​</a></h2><p>第九条因果自律已立原则，第十四条把它落成一道具体的行政手续：报备制。衡元宙的强者能跨位面穿梭，但任何一次跨位面操作——无论目的是外交、救援、考古还是修炼——事前都必须向位面管理局报备，写明目的、人员、时限、预期影响，未批不动。报备不是不信任强者，而是因为跨位面操作的因果影响半径极大，一次冲动的穿越就可能污染两个位面。</p><p>本条款自始至终置于六大顶层公理之下——反掠夺主义公理划底线、万族共和公理立主体、集体升维公理定方向、因果自律公理守边界、法则优先公理保自洽，五者共同构成本条不可逾越的精神边界。</p><p>与前五公理并列，本条同样受公理六·众生全员无限均等法则约束：众生全员无限均等公理——锚点共生文明内所有生灵自带基础无限之力，佛系与懒狗保有保底基础无限而不被时代淘汰，卷王与少年至尊可叠加更多更高层级的无限，掠夺因此从根本上失去意义。</p><h2 id="一、法理依据" tabindex="-1">一、法理依据 <a class="header-anchor" href="#一、法理依据" aria-label="Permalink to &quot;一、法理依据&quot;">​</a></h2><p>本条依据《位面穿梭规则》（地基81）、《跨位面伦理准则》（地基88）与《跨位面锚点连接》（地基28）。跨位面操作直接牵动因果自律公理：只回传知识、不扰动因果。报备制是把这条公理从道德自觉变成行政前置——不是&quot;做了再补登记&quot;，而是&quot;批了才许动&quot;。其法理是认知谦卑：位面至高强者也无法完全预判穿越的全部因果后果，事前申报正是为了让专业机构介入评估。</p><h2 id="二、规范内容-报备制的五项要件" tabindex="-1">二、规范内容：报备制的五项要件 <a class="header-anchor" href="#二、规范内容-报备制的五项要件" aria-label="Permalink to &quot;二、规范内容：报备制的五项要件&quot;">​</a></h2><p>第十四条要求每次跨位面报备必须写明：</p><ol><li>操作目的：外交、救援、考古、修炼还是跨位面贸易</li><li>人员名单：谁去、各自境界与权限</li><li>时限：进入与离开的预计时间点</li><li>预期影响：可能对目标位面造成的扰动范围</li><li>回传方式：只回传知识、不带物质能量的承诺</li></ol><p>五项齐全方可受理，审批通过后发放跨位面通行许可。</p><h2 id="三、适用范围" tabindex="-1">三、适用范围 <a class="header-anchor" href="#三、适用范围" aria-label="Permalink to &quot;三、适用范围&quot;">​</a></h2><p>本条适用于一切具备跨位面穿梭能力的个体与团队，无论其为本位面居民还是外来使团。位面至高强者、多元境强者的报备审查更严——因其因果影响半径更大。未取得通行许可私自穿梭，无论理由为何，一律违宪。本条不适用紧急救援：但救援事后须立即补报并接受因果评估。</p><h2 id="四、违反后果" tabindex="-1">四、违反后果 <a class="header-anchor" href="#四、违反后果" aria-label="Permalink to &quot;四、违反后果&quot;">​</a></h2><p>未批穿梭、报备信息造假、超出许可目的与时限滞留、利用跨位面通道走私掠夺所得，均构成本条违宪。后果为：强制撤回，通行许可暂停；造假与走私按第一条反掠夺从重追究；因私自穿梭引发因果污染的，操作者承担全部因果修正成本，并永久限制跨位面资格。</p><h2 id="五、监督机制" tabindex="-1">五、监督机制 <a class="header-anchor" href="#五、监督机制" aria-label="Permalink to &quot;五、监督机制&quot;">​</a></h2><p>本条由阿赖耶网络+多层监督中的跨位面通行台账执行：每次穿梭的起点、终点、人员、时间全程留痕，与报备记录自动比对，不匹配即告警；位面管理局专设审批与稽查岗；时间法则委员会定期审计报备合规率，杜绝&quot;秘密通道&quot;。</p><h2 id="六、一张被批准的通行证" tabindex="-1">六、一张被批准的通行证 <a class="header-anchor" href="#六、一张被批准的通行证" aria-label="Permalink to &quot;六、一张被批准的通行证&quot;">​</a></h2><p>第十四条在现实中，是一张被批准的通行证。一支考古队计划前往一个陌生位面，他们在报备表里写清了目的、人员、七十二小时观测期、只回传知识的承诺，提交后很快获批。这张通行证不是不信任，而是一道共同的保护——保护他们不因为一时冲动而酿成因果事故，也保护那个陌生位面不被擅自闯入。当跨位面探索变成一种有章可循、人人持证的日常，自由就不必以冒险为代价。报备制看似烦琐，实则让每一次出发都走得安心、回得干净。</p><h2 id="五大核心落点" tabindex="-1">五大核心落点 <a class="header-anchor" href="#五大核心落点" aria-label="Permalink to &quot;五大核心落点&quot;">​</a></h2><ul><li><p>反能级浪费：提前评估避免跨位面操作后的灾难性修正，把隐性成本归零</p></li><li><p>反掠夺：走私、位面殖民都需要跨位面通道，报备制把这条通道置于监控之下</p></li><li><p>唐罗上限对比：唐罗式主角随意穿梭无人管；衡元宙每次穿梭都有报备、有时限、有稽查</p></li><li><p>万族全覆盖：报备对万族使团与个人同等适用，不因族大而免检</p></li><li><p>超多元全开放：报备制让跨位面探索无限扩容而不失控</p></li><li><p>众生全员无限均等：每个生灵自带基础无限之力，佛系懒狗保有保底基础无限而不被淘汰，卷王与少年至尊可叠加更高层级的无限，掠夺因此从根本上失去意义</p></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>跨位面操作报备制，是衡元宙为自由探索戴上的缰绳。缰绳不是为了困住探索，而是为了让探索能一直走下去——走得越远，越要知道自己从哪来、到哪去、留下了什么。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./81-位面穿梭规则.html">81-位面穿梭规则</a> · <a href="./88-跨位面伦理准则.html">88-跨位面伦理准则</a> · <a href="./28-跨位面锚点连接.html">28-跨位面锚点连接</a> · <a href="./905_模块5-第四条-因果自律原则.html">905-第四条因果自律原则</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',26)])])}const c=e(i,[["render",o]]);export{_ as __pageData,c as default};
